initScript:
(() => {
const key="issue101-fixture";
const original=window.fetch.bind(window);
window.__test101=JSON.parse(sessionStorage.getItem(key)||"null")||{profile:{user_id:101,username:"test",name:"测试同学",role:"member",detail:{class:"",student_id:0,qq:"",direction:null,email:"test@example.invalid"}},items:[{direction_code:"front-end"}],puts:[],fail:false,failApplications:false};
localStorage.setItem("iot-pillot.auth",JSON.stringify({user_id:101,access_token:"fixture",refresh_token:"fixture"}));
window.fetch=async(input,init={})=>{
const url=new URL(typeof input==="string"?input:input.url,location.href);
if(!url.pathname.startsWith("/api/"))return original(input,init);
const state=window.__test101;
const ok=data=>new Response(JSON.stringify({code:0,message:"ok",data}),{status:200,headers:{"Content-Type":"application/json"}});
if(url.pathname==="/api/v1/me"){
if(init.method==="PUT"){state.puts.push(JSON.parse(init.body));if(state.fail)return new Response(JSON.stringify({code:5000,message:"保存暂时不可用"}),{status:500});const {name,...detail}=JSON.parse(init.body);state.profile={...state.profile,name:name??"",detail:{...state.profile.detail,...detail}};sessionStorage.setItem(key,JSON.stringify(state));}
return ok(state.profile);}
if(url.pathname==="/api/v1/login"||url.pathname==="/api/v1/register")return ok({user_id:101,access_token:"fixture",refresh_token:"fixture"});
if(url.pathname==="/api/v1/logout")return ok(null);
if(url.pathname==="/api/v1/recruitment/applications"){if(state.failApplications)throw new Error("offline");return ok({items:state.items,total:state.items.length,page:1,page_size:20});}
return ok({items:[]});
};
})();;Object.assign(window.__test101.profile.detail,{class:"",student_id:0,direction:null});window.__test101.items=[{direction_code:"front-end"}];window.__test101.puts=[];window.__test101.fail=false;window.__test101.failApplications=false;

function:
async () => {
const wait=async fn=>{for(let i=0;i<160;i++){if(fn())return;await new Promise(r=>setTimeout(r,25));}throw Error("timeout "+document.body.innerText);};
const click=t=>{const e=[...document.querySelectorAll("button")].find(b=>b.textContent.trim()===t);if(!e)throw Error("button missing "+t);e.click();};
const fill=(s,v)=>{const e=document.querySelector(s);e.value=v;e.dispatchEvent(new Event("input",{bubbles:true}));};
await wait(()=>document.querySelector(".settings"));
if(document.querySelector(".settings input"))throw Error("default editing");
click("更改");await wait(()=>document.querySelector('[placeholder="如：物联网 2301"]'));
click("保存");await wait(()=>document.querySelector("#settings-class-error").textContent.includes("填写"));
if(window.__test101.puts.length)throw Error("invalid PUT");
fill('[placeholder="如：物联网 2301"]',"物联2401");fill('[placeholder="如：2023114514"]',"20240001");
window.__test101.fail=true;click("保存");await wait(()=>document.querySelector(".settings-save-error"));
if(!document.querySelector(".settings input")||document.querySelector('[placeholder="如：物联网 2301"]').value!=="物联2401")throw Error("lost failed draft");
window.__test101.fail=false;click("保存");await wait(()=>!document.querySelector(".settings input"));
if(document.querySelector(".profile-notice"))throw Error("stale reminder");
click("更改");await wait(()=>document.querySelector(".settings input"));
fill('[placeholder="如：物联网 2301"]',"草稿班级");
window.__test101.items=[{direction_code:"back-end"},{direction_code:"front-end"}];
const count=window.__test101.puts.length;click("保存");await wait(()=>document.body.textContent.includes("联系管理员处理"));
if(window.__test101.puts.length!==count)throw Error("conflict PUT");
window.__test101.failApplications=true;click("重新核对方向");
await wait(()=>document.body.textContent.includes("暂时无法核对"));
if(document.querySelector('[placeholder="如：物联网 2301"]').value!=="草稿班级")throw Error("retry lost draft");
window.__test101.failApplications=false;window.__test101.items=[{direction_code:"front-end"}];click("重新核对方向");
await wait(()=>!document.body.textContent.includes("暂时无法核对"));
click("重置");await wait(()=>document.querySelector('[placeholder="如：物联网 2301"]').value==="物联2401");
click("取消");await wait(()=>!document.querySelector(".settings input"));
if(document.querySelector(".settings select"))throw Error("direction still editable");
if(document.querySelector(".settings input[type=email]"))throw Error("email editable");
return {width:innerWidth,overflow:document.documentElement.scrollWidth>innerWidth,passed:["readonly","required","save failure retains draft","save success","notice clears","latest direction conflict blocks PUT","direction request fails closed","retry keeps draft","reset/cancel","email readonly"]};
}
